using Microsoft.EntityFrameworkCore;
using SysAdminAssistant.Core;
using SysAdminAssistant.Infrastructure;
static class DeviceConnectionSpecs
{
 public static async Task Run(string folder,Action<string,bool> check){
 bool Reject(Action f){try{f();return false;}catch(Exception e)when(e is ArgumentException or System.Text.Json.JsonException){return true;}}
 var value=new DeviceConnections("https://router.example:8443/webfig/","server.example",2222,"root","192.168.20.5",3390,@"DOMAIN\admin");check("Connection settings roundtrip without passwords",DeviceConnections.Parse(value.Serialize())==value);check("Empty legacy connection settings disable buttons",DeviceConnections.Parse("").WebUrl==""&&DeviceConnections.Parse("").SshHost==""&&DeviceConnections.Parse("").RdpHost=="");check("SSH fixed argv includes custom port login and option terminator",value.SshArguments().SequenceEqual(new[]{"-p","2222","-l","root","--","server.example"}));check("RDP file contains endpoint and username but no password",value.RdpFile().Contains("full address:s:192.168.20.5:3390\r\n")&&value.RdpFile().Contains("username:s:DOMAIN\\admin\r\n")&&!value.RdpFile().Contains("password"));
 check("IPv6 RDP endpoint gets brackets",(value with{RdpHost="fd00::5"}).RdpFile().Contains("[fd00::5]:3390"));check("IPv6 SSH endpoint is passed as one host argument",(value with{SshHost="[fd00::5]"}).SshArguments()[^1]=="fd00::5");
 foreach(var url in new[]{"file:///C:/Windows/notepad.exe","javascript:alert(1)","ssh://root@host","https://admin:secret@router/","https://host/\ncalc"})check("Unsafe Web target rejected",Reject(()=>(value with{WebUrl=url}).Validate()));
 foreach(var host in new[]{"-oProxyCommand=calc","host;whoami","host/path","https://host/","host\nusername:s:other"})check("Non-host connection target rejected",Reject(()=>(value with{SshHost=host}).Validate()));
 check("RDP line injection rejected",Reject(()=>(value with{RdpUser="admin\r\nremoteapplicationprogram:s:calc"}).Validate()));check("SSH option-shaped login rejected",Reject(()=>(value with{SshUser="-oProxyCommand=calc"}).Validate()));check("Invalid port rejected",Reject(()=>(value with{RdpPort=65536}).Validate()));check("Unexpected secret property rejected",Reject(()=>DeviceConnections.Parse("{\"Password\":\"secret\"}")));
 var factory=new DatabaseFactory(new AppSettings{SqlitePath=Path.Combine(folder,"device-connections.db")});await factory.InitializeAsync();await using(var db=factory.Create()){var d=new Device{Id=3500,Name="Router fixture",Type="MikroTik",Host="192.168.20.1"};db.Add(d);await db.SaveChangesAsync();await db.Database.ExecuteSqlRawAsync("ALTER TABLE sa2_Device DROP COLUMN ConnectionsJson");await BindingSchema.EnsureAsync(db);await BindingSchema.EnsureAsync(db);db.ChangeTracker.Clear();var old=await db.Devices.SingleAsync();check("Connection migration preserves legacy device and empty settings",old.Name==d.Name&&old.ConnectionsJson=="");var prior=RemoteData.EntityStamp(old);old.ConnectionsJson=value.Serialize();check("Connection edit invalidates metadata revision",RemoteData.EntityStamp(old)!=prior);await db.SaveChangesAsync();}
 var archive=Path.Combine(folder,"device-connections.saa");await new DatabaseTransfer(factory).ExportAsync(archive);var copy=new DatabaseFactory(new AppSettings{SqlitePath=Path.Combine(folder,"device-connections-copy.db")});await copy.InitializeAsync();await new DatabaseTransfer(copy).ImportAsync(archive);await using(var db=copy.Create())check("Portable device keeps connection settings",DeviceConnections.Parse((await db.Devices.SingleAsync()).ConnectionsJson)==value);
 }
}
